INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM past_papers p WHERE p.id = 'pp_wassce_soc_2024_2' AND NOT (p.id IS 'pp_wassce_soc_2024_2' AND p.exam_type_id IS 'exam_wassce' AND p.subject_id IS 'subj_wassce_social' AND p.paper_type_id IS 'paper_wassce_2' AND p.year IS '2024' AND p.month IS 'May-June' AND p.series IS 'WASSCE' AND p.title IS 'Social Studies Paper 2 (2024)' AND p.description IS 'WASSCE Social Studies theory practice: essays across governance, social life, economy and environment.' AND p.total_questions IS '9' AND p.total_marks IS '180' AND p.time_allowed IS '120' AND p.instructions IS 'Answer question 1 and any THREE other questions, choosing at least one question from each section.' AND p.is_complete IS '1' AND p.is_premium IS '0' AND p.source_url IS NULL)) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_001' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_gov' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Explain four ways by which the 1992 Constitution of Ghana promotes democracy in the country.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.' AND q.explanation IS 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '1' AND q.section IS 'A' AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_001' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_001' AND NOT (e.question_id IS 'q_soc_2024_2_001' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four relevant constitutional provisions or institutions","marks":8},{"point":"Explains accurately how each provision promotes democracy","marks":8},{"point":"Illustrates points with relevant Ghanaian examples or practice","marks":4}]}' AND e.model_answer IS 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct constitutional provisions identified","Each linked clearly to a democratic principle","Ghanaian examples or practice cited"]' AND e.optional_points IS '["Mention of checks and balances between arms of government","Reference to the independence of the Electoral Commission or judiciary"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_002' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_civ' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Discuss four causes of electoral violence in Ghana and suggest two measures that can be taken to prevent it.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.' AND q.explanation IS 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '2' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Discuss' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_002' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_002' AND NOT (e.question_id IS 'q_soc_2024_2_002' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four plausible causes of electoral violence","marks":8},{"point":"Explains how each cause produces violence","marks":8},{"point":"Suggests two workable preventive measures","marks":4}]}' AND e.model_answer IS 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct causes explained with their mechanisms","Two concrete preventive measures","Balanced, non-partisan treatment"]' AND e.optional_points IS '["Reference to peace pacts or the National Peace Council","Mention of the Vigilantism and Related Offences law"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_003' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_med' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Explain four roles of the media in the national development of Ghana.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.' AND q.explanation IS 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '3' AND q.section IS 'A' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_003' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_003' AND NOT (e.question_id IS 'q_soc_2024_2_003' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four distinct developmental roles of the media","marks":8},{"point":"Explains how each role contributes to national development","marks":8},{"point":"Uses relevant examples of Ghanaian media practice","marks":4}]}' AND e.model_answer IS 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct roles identified","Developmental impact of each role explained","Ghanaian examples included"]' AND e.optional_points IS '["Acknowledgement of limits such as sensationalism or misinformation","Mention of local-language broadcasting"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_004' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_mig' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Discuss four negative effects of rural-urban migration on the rural communities the migrants leave behind.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.' AND q.explanation IS 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '4' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Discuss' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_004' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_004' AND NOT (e.question_id IS 'q_soc_2024_2_004' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four negative effects on the sending rural community","marks":8},{"point":"Explains the mechanism by which each effect harms the community","marks":8},{"point":"Grounds the discussion in Ghanaian rural realities","marks":4}]}' AND e.model_answer IS 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four effects specific to the rural sending community","Mechanisms explained, not just listed","Ghanaian rural context evident"]' AND e.optional_points IS '["Distinction from effects on the receiving urban area","Acknowledgement of possible benefits such as remittances, handled briefly"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_005' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_cul' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Explain four ways by which Ghanaian cultural values can be preserved in the face of globalization.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.' AND q.explanation IS 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '5' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_005' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_005' AND NOT (e.question_id IS 'q_soc_2024_2_005' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four practical preservation strategies","marks":8},{"point":"Explains how each strategy protects a cultural value","marks":8},{"point":"Shows awareness of the pressures globalization creates","marks":4}]}' AND e.model_answer IS 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct preservation strategies","Each tied to a specific cultural value","Globalization pressure acknowledged"]' AND e.optional_points IS '["Role of schools, family, state and media distinguished","Mention of documentation or digital archiving"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_006' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_edu' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Discuss four causes of teenage pregnancy in Ghana and explain two effects it has on the girl''s education.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.' AND q.explanation IS 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '6' AND q.section IS 'B' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Discuss' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_006' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_006' AND NOT (e.question_id IS 'q_soc_2024_2_006' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four plausible causes","marks":8},{"point":"Explains how each cause operates","marks":8},{"point":"Explains two educational effects on the girl","marks":4}]}' AND e.model_answer IS 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct causes with explanations","Two clear educational effects","Sensitive, non-judgemental tone"]' AND e.optional_points IS '["Mention of school re-entry policies","Link between poverty and transactional relationships"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_007' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_eco' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Explain four contributions of agriculture to the economic development of Ghana.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Four creditable contributions: employment — agriculture engages a large share of the labour force in farming, processing and trading; food supply — it feeds the population and keeps urban food prices stable; foreign exchange — cocoa, cashew and other exports earn foreign currency; and raw materials — agro-processing industries depend on farm produce, while farm incomes create demand for manufactured goods. Government also earns revenue through taxes and export levies on the sector. Each contribution is traced through its economic channel with examples such as cocoa exports or the link between farming and agro-processing factories.' AND q.explanation IS 'Four creditable contributions: employment — agriculture engages a large share of the labour force in farming, processing and trading; food supply — it feeds the population and keeps urban food prices stable; foreign exchange — cocoa, cashew and other exports earn foreign currency; and raw materials — agro-processing industries depend on farm produce, while farm incomes create demand for manufactured goods. Government also earns revenue through taxes and export levies on the sector. Each contribution is traced through its economic channel with examples such as cocoa exports or the link between farming and agro-processing factories.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '7' AND q.section IS 'C' AND q.