rking_rubric IS NULL AND e.required_points IS '["Four distinct contributions identified","Economic channel of each explained","Ghanaian examples such as cocoa cited"]' AND e.optional_points IS '["Mention of linkage to agro-processing industry","Reference to export earnings or government revenue"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
