.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '8' AND q.section IS 'C' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Discuss' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_008' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_008' AND NOT (e.question_id IS 'q_soc_2024_2_008' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four environmental effects of illegal mining","marks":8},{"point":"Explains how each effect damages the environment","marks":8},{"point":"Suggests two workable control measures","marks":4}]}' AND e.model_answer IS 'Environmental effects: pollution and siltation of rivers such as the Pra and Ankobra, making water unusable and costly to treat; destruction of forest cover and cocoa farms as land is excavated; mercury and chemical contamination of soil and water, poisoning fish and entering food chains; and abandoned pits that breed mosquitoes and cause deadly accidents. Control measures: strict, impartial enforcement of mining laws with prosecution of financiers, not only labourers; provision of regulated small-scale mining zones with training in safer methods; and sustained public education plus reclamation of mined-out land with tree planting. Each effect is tied to its environmental mechanism.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct environmental effects explained","Two control measures suggested","Ghanaian rivers or mining areas referenced"]' AND e.optional_points IS '["Mention of mercury contamination of food chains","Land reclamation as a remedial measure"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_366_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_soc_2024_2_009' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_emp' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS 'paper_wassce_2' AND q.past_paper_id IS 'pp_wassce_soc_2024_2' AND q.question_text IS 'Explain four measures the government of Ghana can take to reduce unemployment among the youth.' AND q.question_type IS 'essay' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.' AND q.explanation IS 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.' AND q.difficulty IS 'medium' AND q.points IS '20' AND q.marks IS '20' AND q.time_limit IS NULL AND q.question_number IS '9' AND q.section IS 'C' AND q.is_compulsory IS '0' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_soc_2024_2_009' AND NOT (r.batch_id IS 'wassce-paper2-theory-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies Paper 2 theory practice; not official WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://waecgh.org/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM essay_questions e WHERE e.question_id = 'q_soc_2024_2_009' AND NOT (e.question_id IS 'q_soc_2024_2_009' AND e.word_limit_min IS '200' AND e.word_limit_max IS '500' AND e.requires_introduction IS '1' AND e.requires_conclusion IS '1' AND e.marking_scheme IS '{"points":[{"point":"Identifies four plausible government measures","marks":8},{"point":"Explains how each measure creates or sustains jobs","marks":8},{"point":"Relates measures to the situation of Ghanaian youth","marks":4}]}' AND e.model_answer IS 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.' AND e.marking_rubric IS NULL AND e.required_points IS '["Four distinct government measures","Job-creation mechanism of each explained","Youth focus maintained throughout"]' AND e.optional_points IS '["Reference to TVET expansion or entrepreneurship support","Agribusiness promotion as youth employment"]' AND e.ai_grading_enabled IS '1')) THEN 1 ELSE 0 END;
