INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_gov', 'subj_wassce_social', 'Governance and democracy', 'wassce-p2-soc-gov', 'Explain how constitutional provisions and institutions promote democratic governance in Ghana.', 1);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_civ', 'subj_wassce_social', 'Elections and civic life', 'wassce-p2-soc-civ', 'Analyse threats to peaceful elections and propose civic solutions that protect the democratic process.', 2);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_med', 'subj_wassce_social', 'Media and national development', 'wassce-p2-soc-med', 'Assess the roles the media play in education, accountability and national development.', 3);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_mig', 'subj_wassce_social', 'Population and migration', 'wassce-p2-soc-mig', 'Evaluate the causes and consequences of rural-urban migration for sending and receiving communities.', 4);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_cul', 'subj_wassce_social', 'Culture and globalization', 'wassce-p2-soc-cul', 'Explain how Ghanaian cultural values can be preserved amid globalizing influences.', 5);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_edu', 'subj_wassce_social', 'Adolescent health and education', 'wassce-p2-soc-edu', 'Analyse the causes of teenage pregnancy and its consequences for girls'' education and life chances.', 6);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_eco', 'subj_wassce_social', 'Agriculture and the economy', 'wassce-p2-soc-eco', 'Explain the contribution of agriculture to employment, food security and industrial growth in Ghana.', 7);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_env', 'subj_wassce_social', 'Environment and illegal mining', 'wassce-p2-soc-env', 'Evaluate the environmental and social effects of illegal mining and the measures available to control it.', 8);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_wassce_p2_soc_emp', 'subj_wassce_social', 'Work and unemployment', 'wassce-p2-soc-emp', 'Propose and assess measures government can take to reduce unemployment among the youth.', 9);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_001', 'topic_wassce_p2_soc_gov', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Explain four ways by which the 1992 Constitution of Ghana promotes democracy in the country.', 'essay', NULL, NULL, 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.', 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.', 'medium', '20', '20', NULL, '1', 'A', '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_002', 'topic_wassce_p2_soc_civ', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Discuss four causes of electoral violence in Ghana and suggest two measures that can be taken to prevent it.', 'essay', NULL, NULL, 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.', 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.', 'medium', '20', '20', NULL, '2', 'A', '0', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_003', 'topic_wassce_p2_soc_med', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Explain four roles of the media in the national development of Ghana.', 'essay', NULL, NULL, 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.', 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.', 'medium', '20', '20', NULL, '3', 'A', '0', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_004', 'topic_wassce_p2_soc_mig', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Discuss four negative effects of rural-urban migration on the rural communities the migrants leave behind.', 'essay', NULL, NULL, 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.', 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.', 'medium', '20', '20', NULL, '4', 'B', '0', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_005', 'topic_wassce_p2_soc_cul', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Explain four ways by which Ghanaian cultural values can be preserved in the face of globalization.', 'essay', NULL, NULL, 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.', 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.', 'medium', '20', '20', NULL, '5', 'B', '0', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_006', 'topic_wassce_p2_soc_edu', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Discuss four causes of teenage pregnancy in Ghana and explain two effects it has on the girl''s education.', 'essay', NULL, NULL, 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.', 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.', 'medium', '20', '20', NULL, '6', 'B', '0', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_007', 'topic_wassce_p2_soc_eco', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Explain four contributions of agriculture to the economic development of Ghana.', 'essay', NULL, NULL, 'Four creditable contributions: employment — agriculture engages a large share of the labour force in farming, processing and trading; food supply — it feeds the population and keeps urban food prices stable; foreign exchange — cocoa, cashew and other exports earn foreign currency; and raw materials — agro-processing industries depend on farm produce, while farm incomes create demand for manufactured goods. Government also earns revenue through taxes and export levies on the sector. Each contribution is traced through its economic channel with examples such as cocoa exports or the link between farming and agro-processing factories.', 'Four creditable contributions: employment — agriculture engages a large share of the labour force in farming, processing and trading; food supply — it feeds the population and keeps urban food prices stable; foreign exchange — cocoa, cashew and other exports earn foreign currency; and raw materials — agro-processing industries depend on farm produce, while farm incomes create demand for manufactured goods. Government also earns revenue through taxes and export levies on the sector. Each contribution is traced through its economic channel with examples such as cocoa exports or the link between farming and agro-processing factories.', 'medium', '20', '20', NULL, '7', 'C', '0', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_008', 'topic_wassce_p2_soc_env', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Discuss four effects of illegal mining (galamsey) on the environment in Ghana and suggest two measures to control the practice.', 'essay', NULL, NULL, 'Environmental effects: pollution and siltation of rivers such as the Pra and Ankobra, making water unusable and costly to treat; destruction of forest cover and cocoa farms as land is excavated; mercury and chemical contamination of soil and water, poisoning fish and entering food chains; and abandoned pits that breed mosquitoes and cause deadly accidents. Control measures: strict, impartial enforcement of mining laws with prosecution of financiers, not only labourers; provision of regulated small-scale mining zones with training in safer methods; and sustained public education plus reclamation of mined-out land with tree planting. Each effect is tied to its environmental mechanism.', 'Environmental effects: pollution and siltation of rivers such as the Pra and Ankobra, making water unusable and costly to treat; destruction of forest cover and cocoa farms as land is excavated; mercury and chemical contamination of soil and water, poisoning fish and entering food chains; and abandoned pits that breed mosquitoes and cause deadly accidents. Control measures: strict, impartial enforcement of mining laws with prosecution of financiers, not only labourers; provision of regulated small-scale mining zones with training in safer methods; and sustained public education plus reclamation of mined-out land with tree planting. Each effect is tied to its environmental mechanism.', 'medium', '20', '20', NULL, '8', 'C', '0', NULL, NULL, 'Discuss', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_soc_2024_2_009', 'topic_wassce_p2_soc_emp', 'subj_wassce_social', 'exam_wassce', 'paper_wassce_2', 'pp_wassce_soc_2024_2', 'Explain four measures the government of Ghana can take to reduce unemployment among the youth.', 'essay', NULL, NULL, 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.', 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.', 'medium', '20', '20', NULL, '9', 'C', '0', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_001', 'q_soc_2024_2_001', '200', '500', '1', '1', '{"points":[{"point":"Identifies four relevant constitutional provisions or institutions","marks":8},{"point":"Explains accurately how each provision promotes democracy","marks":8},{"point":"Illustrates points with relevant Ghanaian examples or practice","marks":4}]}', 'A strong answer explains four of: separation of powers among the Executive, Legislature and Judiciary so no arm dominates; the Bill of Rights (fundamental human rights in Chapter 5) protecting freedoms of speech, association and movement; provision for periodic, universal-suffrage elections through an independent Electoral Commission; an independent judiciary empowered to review and strike down unconstitutional acts; and recognition of a multi-party system allowing competition for power. Each point is developed to show the democratic principle it serves, with examples such as peaceful changes of government through elections.', NULL, '["Four distinct constitutional provisions identified","Each linked clearly to a democratic principle","Ghanaian examples or practice cited"]', '["Mention of checks and balances between arms of government","Reference to the independence of the Electoral Commission or judiciary"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_002', 'q_soc_2024_2_002', '200', '500', '1', '1', '{"points":[{"point":"Identifies four plausible causes of electoral violence","marks":8},{"point":"Explains how each cause produces violence","marks":8},{"point":"Suggests two workable preventive measures","marks":4}]}', 'Credible causes include: winner-takes-all politics, which raises the stakes of every election; mistrust of the Electoral Commission or security agencies by losing parties; the activities of party militias and vigilante groups; ethnic or religious campaigning that inflames divisions; and youth unemployment, which makes young people available for paid violence. Preventive measures: continuous voter and peace education by the NCCE, civil society and religious bodies, and firm, impartial enforcement of the law against vigilante groups together with dialogue platforms such as the National Peace Council bringing parties to sign peace pacts. Each cause must be tied to the mechanism by which it produces violence.', NULL, '["Four distinct causes explained with their mechanisms","Two concrete preventive measures","Balanced, non-partisan treatment"]', '["Reference to peace pacts or the National Peace Council","Mention of the Vigilantism and Related Offences law"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_003', 'q_soc_2024_2_003', '200', '500', '1', '1', '{"points":[{"point":"Identifies four distinct developmental roles of the media","marks":8},{"point":"Explains how each role contributes to national development","marks":8},{"point":"Uses relevant examples of Ghanaian media practice","marks":4}]}', 'Four creditable roles: education and information dissemination — radio and television carry health campaigns, agricultural extension advice and civic education in local languages; watchdog over those in power — investigative reporting exposes corruption and prompts accountability; a platform for public discussion — phone-in programmes let citizens influence policy between elections; and promotion of culture and national unity — broadcasting festivals, languages and national events. The media also support economic activity through advertising and market information. Each role is developed with a Ghanaian example such as community radio or televised national events.', NULL, '["Four distinct roles identified","Developmental impact of each role explained","Ghanaian examples included"]', '["Acknowledgement of limits such as sensationalism or misinformation","Mention of local-language broadcasting"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_004', 'q_soc_2024_2_004', '200', '500', '1', '1', '{"points":[{"point":"Identifies four negative effects on the sending rural community","marks":8},{"point":"Explains the mechanism by which each effect harms the community","marks":8},{"point":"Grounds the discussion in Ghanaian rural realities","marks":4}]}', 'A strong answer keeps the focus on the sending community: loss of energetic young labour, which lowers farm output and leaves agriculture to the aged; depopulation, which makes schools and clinics lose enrolment and staff and can lead to their closure; breakdown of extended-family care, leaving children and the elderly without support; and slower local development as the most educated and enterprising residents leave. Some answers add that traditional festivals and communal labour decline. Each effect is explained through its mechanism rather than merely listed, with examples drawn from farming and community life.', NULL, '["Four effects specific to the rural sending community","Mechanisms explained, not just listed","Ghanaian rural context evident"]', '["Distinction from effects on the receiving urban area","Acknowledgement of possible benefits such as remittances, handled briefly"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_005', 'q_soc_2024_2_005', '200', '500', '1', '1', '{"points":[{"point":"Identifies four practical preservation strategies","marks":8},{"point":"Explains how each strategy protects a cultural value","marks":8},{"point":"Shows awareness of the pressures globalization creates","marks":4}]}', 'Creditable strategies: teaching Ghanaian languages, history and cultural studies in schools so children internalize them early; deliberate family transmission — parents speaking mother tongues at home and involving children in festivals, naming ceremonies and storytelling; documentation and promotion through museums, cultural centres and media; and state support for festivals, traditional authorities and creative arts that keep crafts, music and dance economically viable. Each way should name the value it protects — respect for elders, communal solidarity, hospitality — and acknowledge the globalizing pressure it answers, such as foreign media content or urban lifestyles.', NULL, '["Four distinct preservation strategies","Each tied to a specific cultural value","Globalization pressure acknowledged"]', '["Role of schools, family, state and media distinguished","Mention of documentation or digital archiving"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_006', 'q_soc_2024_2_006', '200', '500', '1', '1', '{"points":[{"point":"Identifies four plausible causes","marks":8},{"point":"Explains how each cause operates","marks":8},{"point":"Explains two educational effects on the girl","marks":4}]}', 'Creditable causes: poverty, which pushes girls into transactional relationships for basic needs; inadequate sexuality education at home and school; peer pressure and exposure to explicit media; and broken homes or weak parental supervision. Educational effects: many girls drop out or are withdrawn, cutting short their schooling and qualifications; even where re-entry is possible, pregnancy and childcare interrupt learning, lower performance and narrow future career options. The best answers treat the subject sensitively, avoid blame, and show how the causes interact with economic circumstances.', NULL, '["Four distinct causes with explanations","Two clear educational effects","Sensitive, non-judgemental tone"]', '["Mention of school re-entry policies","Link between poverty and transactional relationships"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_007', 'q_soc_2024_2_007', '200', '500', '1', '1', '{"points":[{"point":"Identifies four distinct economic contributions of agriculture","marks":8},{"point":"Explains the channel through which each contribution works","marks":8},{"point":"Supports points with Ghanaian examples such as cocoa","marks":4}]}', 'Four creditable contributions: employment — agriculture engages a large share of the labour force in farming, processing and trading; food supply — it feeds the population and keeps urban food prices stable; foreign exchange — cocoa, cashew and other exports earn foreign currency; and raw materials — agro-processing industries depend on farm produce, while farm incomes create demand for manufactured goods. Government also earns revenue through taxes and export levies on the sector. Each contribution is traced through its economic channel with examples such as cocoa exports or the link between farming and agro-processing factories.', NULL, '["Four distinct contributions identified","Economic channel of each explained","Ghanaian examples such as cocoa cited"]', '["Mention of linkage to agro-processing industry","Reference to export earnings or government revenue"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_008', 'q_soc_2024_2_008', '200', '500', '1', '1', '{"points":[{"point":"Identifies four environmental effects of illegal mining","marks":8},{"point":"Explains how each effect damages the environment","marks":8},{"point":"Suggests two workable control measures","marks":4}]}', 'Environmental effects: pollution and siltation of rivers such as the Pra and Ankobra, making water unusable and costly to treat; destruction of forest cover and cocoa farms as land is excavated; mercury and chemical contamination of soil and water, poisoning fish and entering food chains; and abandoned pits that breed mosquitoes and cause deadly accidents. Control measures: strict, impartial enforcement of mining laws with prosecution of financiers, not only labourers; provision of regulated small-scale mining zones with training in safer methods; and sustained public education plus reclamation of mined-out land with tree planting. Each effect is tied to its environmental mechanism.', NULL, '["Four distinct environmental effects explained","Two control measures suggested","Ghanaian rivers or mining areas referenced"]', '["Mention of mercury contamination of food chains","Land reclamation as a remedial measure"]', '1');
INSERT OR IGNORE INTO essay_questions (id, question_id, word_limit_min, word_limit_max, requires_introduction, requires_conclusion, marking_scheme, model_answer, marking_rubric, required_points, optional_points, ai_grading_enabled) VALUES ('eq_q_soc_2024_2_009', 'q_soc_2024_2_009', '200', '500', '1', '1', '{"points":[{"point":"Identifies four plausible government measures","marks":8},{"point":"Explains how each measure creates or sustains jobs","marks":8},{"point":"Relates measures to the situation of Ghanaian youth","marks":4}]}', 'Creditable measures: expanding technical and vocational education so young people gain employable, practical skills; supporting entrepreneurship through start-up credit, training and business incubation; promoting agriculture as a business with inputs, credit and ready markets to draw youth into agribusiness; and attracting investment into industry and services through tax incentives and infrastructure, creating formal jobs. Public employment programmes and digitization of the economy are also creditable. Each measure is explained in terms of how it creates or sustains employment for young people rather than merely named.', NULL, '["Four distinct government measures","Job-creation mechanism of each explained","Youth focus maintained throughout"]', '["Reference to TVET expansion or entrepreneurship support","Agribusiness promotion as youth employment"]', '1');
