v', 'topic_wassce_p2_soc_emp')) = 9 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id WHERE q.id IN ('q_soc_2024_2_001', 'q_soc_2024_2_002', 'q_soc_2024_2_003', 'q_soc_2024_2_004', 'q_soc_2024_2_005', 'q_soc_2024_2_006', 'q_soc_2024_2_007', 'q_soc_2024_2_008', 'q_soc_2024_2_009')) = 9 AND (SELECT COUNT(*) FROM essay_questions WHERE question_id IN ('q_soc_2024_2_001', 'q_soc_2024_2_002', 'q_soc_2024_2_003', 'q_soc_2024_2_004', 'q_soc_2024_2_005', 'q_soc_2024_2_006', 'q_soc_2024_2_007', 'q_soc_2024_2_008', 'q_soc_2024_2_009')) = 9 THEN 1 ELSE 0 END;
